PRAGMA foreign_keys=ON;
CREATE TABLE SimulationRun(run_id TEXT PRIMARY KEY,seed INTEGER NOT NULL,mode TEXT NOT NULL,scenario_type TEXT NOT NULL,data_class TEXT NOT NULL);
CREATE TABLE ExperimentAssignment(user_id TEXT PRIMARY KEY,pair_id TEXT,sample_set_type TEXT NOT NULL CHECK(sample_set_type IN('control','treatment')),sample_stratum TEXT NOT NULL,intent_segment TEXT NOT NULL,treatment_policy TEXT NOT NULL,template_cluster_id TEXT NOT NULL,run_id TEXT NOT NULL REFERENCES SimulationRun(run_id),random_seed INTEGER NOT NULL,scenario_type TEXT NOT NULL,distribution_lineage_policy TEXT NOT NULL);
CREATE TABLE Search(search_id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES ExperimentAssignment(user_id),session_id TEXT NOT NULL,search_seq INTEGER NOT NULL,search_at TEXT NOT NULL,total_result_count INTEGER NOT NULL CHECK(total_result_count>=0),condition_signature TEXT NOT NULL,behavior_from_previous TEXT,UNIQUE(user_id,search_seq));
CREATE TABLE SearchFilter(search_id TEXT PRIMARY KEY REFERENCES Search(search_id),region_group TEXT NOT NULL,price_limit REAL,option_limit_count INTEGER NOT NULL,query_variant TEXT NOT NULL,continuous_preference REAL NOT NULL CHECK(continuous_preference BETWEEN 0 AND 1));
CREATE TABLE HotelDimension(hotel_key INTEGER PRIMARY KEY,hotel_cluster_id TEXT NOT NULL UNIQUE);
CREATE TABLE RoomDimension(room_key INTEGER PRIMARY KEY,hotel_key INTEGER NOT NULL REFERENCES HotelDimension(hotel_key),room_type TEXT NOT NULL);
CREATE TABLE SearchResult(search_result_id TEXT PRIMARY KEY,search_id TEXT NOT NULL REFERENCES Search(search_id),hotel_key INTEGER NOT NULL REFERENCES HotelDimension(hotel_key),room_key INTEGER NOT NULL REFERENCES RoomDimension(room_key),result_rank INTEGER NOT NULL,UNIQUE(search_id,result_rank));
CREATE TABLE ActionEvent(event_id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES ExperimentAssignment(user_id),search_id TEXT REFERENCES Search(search_id),event_type TEXT NOT NULL CHECK(event_type IN('search_submit','treatment_exposure','proposal_selected','hotel_detail_view','session_end')),event_at TEXT NOT NULL,hotel_key INTEGER REFERENCES HotelDimension(hotel_key),paired_mirror_event INTEGER NOT NULL DEFAULT 0 CHECK(paired_mirror_event=0));
CREATE TABLE SearchTransition(transition_id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES ExperimentAssignment(user_id),from_search_id TEXT NOT NULL REFERENCES Search(search_id),to_search_id TEXT NOT NULL REFERENCES Search(search_id),behavior TEXT NOT NULL CHECK(behavior IN('same','region','price_relax','option_relax','query','mixed')),recovered INTEGER NOT NULL CHECK(recovered IN(0,1)),interarrival_seconds INTEGER NOT NULL CHECK(interarrival_seconds>0));
CREATE TABLE SessionSummary(session_id TEXT PRIMARY KEY,user_id TEXT NOT NULL UNIQUE REFERENCES ExperimentAssignment(user_id),search_count INTEGER NOT NULL,experienced_zero INTEGER NOT NULL,final_recovered INTEGER NOT NULL,card_h_search_count INTEGER NOT NULL,card_h_event_count INTEGER NOT NULL,session_start_at TEXT NOT NULL,session_end_at TEXT NOT NULL,outcome_segment TEXT NOT NULL CHECK(outcome_segment IN('SG1','SG2','SG3','SG4')));
CREATE TABLE _generation_metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE INDEX ix_search_session_seq ON Search(session_id,search_seq);
CREATE INDEX ix_result_search_rank ON SearchResult(search_id,result_rank);
CREATE INDEX ix_event_search_type ON ActionEvent(search_id,event_type);
